(gen_random_uuid(), 'fe032b75-9064-4677-8e55-37c6394b204c', 'Nurofen Express capsule moi calmeaza rapid durerea de cap, migrenele, durerile musculare sau reumatismale. Calmarea durerii depinde insa si de cat de usor se descompune si absoarbe medicamentul in corp. Nurofen Express 200 mg capsule moi se absoarbe rapid de catre organism, tintind chiar locul dureros. Datorita compozitiei sale Nurofen Express calmeaza rapid si isi face prompt si eficient efectul chiar la sursa durerii. Astfel recastigi starea de bine si te poti bucura de fiecare moment.
INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), 'c88b5095-fb1f-4a97-a4d1-1fbb4597b3fa', 'Indicatii:Nurofen Express este utilizat pentru:- ameliorarea durerilor uşoare până la moderate, cum sunt dureri de cap, durerile de dinți şi- reducerea febrei şi durerii asociate cu răceala comună.
INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), '8334a8a8-749f-4e2d-bbf9-75f3a07db952', 'Nurofen express 200 mg capsule moi este utilizat pentru calmarea durerilor usoare pana la moderate, are efect antinflamator, analgezic, antipiretic. Actioneaza rapid asupra sursei durerii si se absoare rapid în fluxul sanguin', 'Antiinflamatoare', 'Fără efecte secundare cunoscute', 'ro');
