INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), 'bd154714-9758-4e08-bc15-0b44da2ad617', 'Indicatii:- Paracetamol Zentiva face parte din grupa medicamentelor analgezice-antipiretice (ameliorează durerea şi reduce temperatura corpului în caz de febră);- Paracetamol Zentiva este indicat în tratamentul simptomatic al durerilor de intensitate uşoară până la moderată, cu diferite localizări (dureri de cap, dureri în gât, dureri de dinţi, dureri asociate răcelii şi gripei, dureri ale muşchilor sau articulaţiilor sau în caz de menstruaţie dureroasă) şi tratamentul simptomatic al febrei.
INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), '93f9d1d2-3c67-4083-8c01-b332617582a5', 'Ce este Strepsils Miere si Lamaie si pentru ce se utilizeaza:
INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), 'bceea1c7-3c83-4a37-8370-66f886540255', 'Indicatii:Strepsils Miere şi Lămâie aparţine unei grupe de medicamente denumite antiseptice.Strepsils Miere şi Lămâie se utilizează ca adjuvant în tratamentul infecţiilor oro-faringiene, favorizând ameliorarea simptomelor provocate de acestea.Calmare rapidă (în 5 minute) şi de lungă durată (de până la 2 ore) a durerii în gât.Efect antibacterian, antifungic şi antiviral.
INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), '5df9a655-5313-46f1-a869-b70595813b0f', 'Strepsils Miere și Lămâie oferă o calmare rapidă și eficientă a durerii în gât, activând încă de la primele semne ale durerii. Formula sa include ingrediente antiseptice pentru combaterea infecțiilor bacteriene și este îmbogățită cu miere și lămâie pentru un efect emolient și o aromă plăcută.', 'Dureri de gat', 'Fără efecte secundare cunoscute', 'ro');
