INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), '6a125ae4-564f-49c6-8317-21c6520ffc02', 'Indicatii:Coldrex Maxgrip Lemon este un medicament impotriva racelii si gripei care contine trei substante active:- paracetamol care amelioreaza durerea si reduce temperatura atunci cand aveti febra;- clorhidratul de fenilefrina este un decongestionant care desfunda nasul si sinusurile si va ajuta sa respirati mai usor;- vitamina C (acidul ascorbic) inlocuieste vitamina C care se pierde in primele stadii de raceala si gripa.
