(gen_random_uuid(), 'a3559fdb-41c9-4684-80d2-85bc3834078b', 'Ce este Aspacardin si pentru ce se utilizeaza
INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), 'aec7e00a-3c49-4763-a452-f1443b14da18', 'Indicatii:Aspacardin face parte din grupa de medicamente numite suplimente minerale, medicamente cu potasiu. Acţionează asupra inimii şi vaselor de sânge fiind utilizat ca terapie adjuvantă la adulţi în boala coronariană (boala vaselor de sânge ale inimii), în anumite tulburări de ritm cadiac şi pentru prevenţia tulburărilor de ritm cardiac care pot să apară după tratamentul cu unele medicamente numite glicozide tonicardiace.
INSERT INTO items_translation (id_translation, id, description, category, side_effects, language) VALUES
(gen_random_uuid(), 'c7a1103c-300a-43b3-9d60-be155cdde12c', 'Aspacardin face parte din grupa de medicamente numite suplimente minerale, medicamente cu potasiu care actioneaza asupra inimii si vaselor de sange', 'Cardiace si Tensiune', 'Fără efecte secundare cunoscute', 'ro');
